rows=[]
for (nid, name, buyer, check, margin, freq, season, comp, avito, mp, log, order, commis, risk, sc) in P:
    assert len(sc)==5, name
    score = round(sum(sc[i]*W[k] for i,k in enumerate(ORDER)), 2)
    rows.append(dict(nisha_id=nid, tovar=name, pokupatel=buyer, chek_ocenka=check,
                     marzha_ocenka_rub=margin, chastota=freq, sezonnost=season,
                     konkurenciya=comp, avito_potencial=avito, wb_ozon=mp,
                     logistika=log, pod_zakaz=order, komissiya=commis, risk=risk,
                     b_bez_zakupki=sc[0], b_zashchita_ot_MP=sc[1], b_marzha=sc[2],
                     b_chek=sc[3], b_skorost=sc[4], SCORE=score))

rows.sort(key=lambda r:-r["SCORE"])
for i,r in enumerate(rows,1): r["rank"]=i

fields=["rank","nisha_id","tovar","pokupatel","chek_ocenka","marzha_ocenka_rub","chastota",
        "sezonnost","konkurenciya","avito_potencial","wb_ozon","logistika","pod_zakaz",
        "komissiya","risk","b_bez_zakupki","b_zashchita_ot_MP","b_marzha","b_chek","b_skorost","SCORE"]
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "PRODUCT_MATRIX.csv")
with open(out,"w",encoding="utf-8",newline="") as f:
    w=csv.DictWriter(f,fieldnames=fields,delimiter=";"); w.writeheader()
    for r in rows: w.writerow({k:r[k] for k in fields})

